package com.example;

import java.util.Objects;

public class User {
    private final String id;

    public User(String id) {
        this.id = id;
    }

    @Override
    public boolean equals(Object other) {
        if (!(other instanceof User)) {
            return false;
        }
        return Objects.equals(id, ((User) other).id);
    }
}
